<template>
  <div class="admin-container">
    <!-- 侧边栏 -->
    <aside class="admin-sidebar">
      <div class="sidebar-header">
        <h2>管理后台</h2>
      </div>
      <el-menu
        :default-active="activeMenu"
        class="admin-menu"
        background-color="#304156"
        text-color="#bfcbd9"
        active-text-color="#409EFF"
        router
      >
        <el-menu-item index="/admin/dashboard">
          <template slot="title">
            <i class="el-icon-home" style="font-size: 16px; margin-right: 8px;"></i>
            <span>仪表盘</span>
          </template>
        </el-menu-item>
        <el-menu-item index="/admin/articles">
          <template slot="title">
            <i class="el-icon-document" style="font-size: 16px; margin-right: 8px;"></i>
            <span>文章管理</span>
          </template>
        </el-menu-item>
        <el-menu-item index="/admin/comments">
          <template slot="title">
            <i class="el-icon-message" style="font-size: 16px; margin-right: 8px;"></i>
            <span>评论管理</span>
          </template>
        </el-menu-item>
        <el-menu-item index="/admin/users">
          <template slot="title">
            <i class="el-icon-user" style="font-size: 16px; margin-right: 8px;"></i>
            <span>用户管理</span>
          </template>
        </el-menu-item>
        <el-menu-item index="/admin/categories">
          <template slot="title">
            <i class="el-icon-folder" style="font-size: 16px; margin-right: 8px;"></i>
            <span>分类管理</span>
          </template>
        </el-menu-item>
        <el-menu-item index="/admin/tags">
          <template slot="title">
            <i class="el-icon-tag" style="font-size: 16px; margin-right: 8px;"></i>
            <span>标签管理</span>
          </template>
        </el-menu-item>
      </el-menu>
    </aside>

    <!-- 主内容区 -->
    <div class="admin-main">
      <!-- 顶部导航 -->
      <header class="admin-header">
        <div class="header-left">
          <el-breadcrumb separator="/">
            <el-breadcrumb-item :to="{ path: '/admin/dashboard' }">首页</el-breadcrumb-item>
            <el-breadcrumb-item v-if="$route.name !== 'Dashboard'">{{ $route.name }}</el-breadcrumb-item>
          </el-breadcrumb>
        </div>
        <div class="header-right">
          <el-dropdown @command="handleCommand">
            <span class="user-info">
              <i class="el-icon-user-solid"></i>
              {{ adminNickname }}
              <i class="el-icon-arrow-down el-icon--right"></i>
            </span>
            <el-dropdown-menu slot="dropdown">
              <el-dropdown-item command="home">返回首页</el-dropdown-item>
              <el-dropdown-item command="logout">退出登录</el-dropdown-item>
            </el-dropdown-menu>
          </el-dropdown>
        </div>
      </header>

      <!-- 内容区域 -->
      <div class="admin-content">
        <router-view></router-view>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  name: 'AdminLayout',
  computed: {
    adminNickname() {
      return this.$store.state.account || this.$store.state.name || '管理员'
    },
    activeMenu() {
      const path = this.$route.path
      if (path.startsWith('/admin/dashboard')) return '/admin/dashboard'
      if (path.startsWith('/admin/articles')) return '/admin/articles'
      if (path.startsWith('/admin/comments')) return '/admin/comments'
      if (path.startsWith('/admin/users')) return '/admin/users'
      if (path.startsWith('/admin/categories')) return '/admin/categories'
      if (path.startsWith('/admin/tags')) return '/admin/tags'
      return '/admin/dashboard'
    }
  },
  methods: {
    handleCommand(command) {
      if (command === 'home') {
        this.$router.push('/')
      } else if (command === 'logout') {
        this.$store.dispatch('logout').then(() => {
          this.$router.push('/login')
        })
      }
    }
  }
}
</script>

<style scoped>
.admin-container {
  display: flex;
  height: 100vh;
  background-color: #f0f2f5;
}

.admin-sidebar {
  width: 200px;
  background-color: #304156;
  height: 100vh;
  overflow-y: auto;
}

.sidebar-header {
  padding: 20px;
  text-align: center;
  color: #fff;
  background-color: #263445;
}

.sidebar-header h2 {
  margin: 0;
  font-size: 18px;
}

.admin-menu {
  border-right: none;
}

.admin-menu i {
  font-size: 18px;
  margin-right: 8px;
  color: #bfcbd9;
}

.admin-menu .el-menu-item {
  display: flex;
  align-items: center;
}

.admin-main {
  flex: 1;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.admin-header {
  height: 60px;
  background-color: #fff;
  box-shadow: 0 1px 4px rgba(0, 21, 41, 0.08);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 20px;
}

.header-left {
  display: flex;
  align-items: center;
}

.header-right {
  display: flex;
  align-items: center;
}

.user-info {
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 8px;
  color: #606266;
}

.user-info:hover {
  color: #409EFF;
}

.admin-content {
  flex: 1;
  padding: 20px;
  overflow-y: auto;
}

/* 手机端适配 (max-width: 767px) */
@media screen and (max-width: 767px) {
  .admin-sidebar {
    width: 50px;
  }

  .sidebar-header {
    padding: 10px;
  }

  .sidebar-header h2 {
    display: none;
  }

  .el-menu-item span {
    display: none;
  }

  .admin-header {
    padding: 0 10px;
  }

  .admin-content {
    padding: 10px;
  }
}

/* 平板端适配 (768px - 1024px) */
@media screen and (min-width: 768px) and (max-width: 1024px) {
  .admin-sidebar {
    width: 160px;
  }

  .sidebar-header h2 {
    font-size: 14px;
  }

  .el-menu-item span {
    font-size: 13px;
  }

  .admin-content {
    padding: 15px;
  }
}

/* 桌面端适配 (min-width: 1025px) */
@media screen and (min-width: 1025px) {
  .admin-content {
    padding: 20px;
    max-width: 1400px;
    margin: 0 auto;
  }
}
</style>



